def backfill_received(apps, schema_editor):
    """
    Purchases received before deliveries existed arrived in full: mark every
    line received and record one delivery for it.
    """
    Purchase = apps.get_model("purchases", "Purchase")
    PurchaseItem = apps.get_model("purchases", "PurchaseItem")
    PurchaseReceipt = apps.get_model("purchases", "PurchaseReceipt")
    PurchaseReceiptItem = apps.get_model("purchases", "PurchaseReceiptItem")

    for purchase in Purchase.objects.filter(status="received"):
        day = (
            purchase.received_at.date() if purchase.received_at
            else purchase.purchase_date
        )
        receipt = PurchaseReceipt.objects.create(
            purchase=purchase, received_on=day, received_by=purchase.received_by
        )

        for item in PurchaseItem.objects.filter(purchase=purchase):
            item.received_quantity = item.quantity
            item.save(update_fields=["received_quantity"])
            PurchaseReceiptItem.objects.create(
                receipt=receipt, purchase_item=item, quantity=item.quantity
            )


